**Assumptions.** The question mentions three switches but specifies two input pins and four states. Use two externally pulled-down switches for PB5/PB4, with a closed switch reading 1. Generate one active-high pulse on PC3 at startup and after each stable change of selector value. Assume 16 MHz and exclusive use of Timers 1 and 3.

In CTC the compare interval is $(\mathrm{OCRnA}+1)N/f_{\mathrm{CPU}}$. For one second:

| PB5:PB4 | Timer | Prescaler | CS bits | OCRnA |
| :---: | :---: | ---: | :---: | ---: |
| 00 | 1 | 256 | 100 | 62499 |
| 01 | 1 | 1024 | 101 | 15624 |
| 10 | 3 | 256 | 100 | 62499 |
| 11 | 3 | 1024 | 101 | 15624 |

```cpp
#include <Arduino.h>

constexpr uint8_t selectorMask = _BV(PB5) | _BV(PB4);
constexpr uint8_t pulseMask = _BV(PC3);

uint8_t readSelection() {
    return (PINB & selectorMask) >> PB4;
}

void pulseFor(uint8_t selection) {
    const bool timer3 = selection & 2;
    const bool div1024 = selection & 1;
    const uint16_t compare = div1024 ? 15624 : 62499;

    if (timer3) {
        TCCR3B = 0;
        TCNT3 = 0;
        OCR3A = compare;
        TIFR3 = _BV(OCF3A);
        PORTC |= pulseMask;
        TCCR3B = _BV(WGM32) | _BV(CS32) | (div1024 ? _BV(CS30) : 0);
        while (!(TIFR3 & _BV(OCF3A))) {}
        PORTC &= ~pulseMask;
        TCCR3B = 0;
        TIFR3 = _BV(OCF3A);
    } else {
        TCCR1B = 0;
        TCNT1 = 0;
        OCR1A = compare;
        TIFR1 = _BV(OCF1A);
        PORTC |= pulseMask;
        TCCR1B = _BV(WGM12) | _BV(CS12) | (div1024 ? _BV(CS10) : 0);
        while (!(TIFR1 & _BV(OCF1A))) {}
        PORTC &= ~pulseMask;
        TCCR1B = 0;
        TIFR1 = _BV(OCF1A);
    }
}

void setup() {
    DDRB &= ~selectorMask;
    PORTB &= ~selectorMask;  // External pull-downs.
    PORTC &= ~pulseMask;
    DDRC |= pulseMask;
    TCCR1B = 0;
    TCCR3B = 0;
    TCCR1A = 0;
    TCCR3A = 0;
    TIMSK1 = 0;
    TIMSK3 = 0;
}

void loop() {
    static uint8_t lastSelection = 0xFF;
    const uint8_t selection = readSelection();
    if (selection == lastSelection) return;
    delay(20);
    if (selection != readSelection()) return;

    pulseFor(selection);
    lastSelection = selection;
}
```

PC3 is software-driven. The timer sets a nominal one-second interval with small software edge latency. The counts are derived independently for each exam prescaler.

Use **ADC0/PF0/A0**, **ADC1/PF1/A1** and **ADC3/PF3/A3** with low-impedance sources and a shared ground. Assume a 16 MHz Mega 2560, a 5 V AVCC reference with an AREF bypass capacitor and a divider of 128 for 125 kHz. Send the upper eight bits from left-adjusted `ADCH` to `PORTA`.

Use active-high LEDs with series resistors on PB2, PB3 and PB4. Turn off the other two whenever the selected channel's result is displayed.

```cpp
#include <Arduino.h>

constexpr uint8_t adcControl = _BV(ADEN) | _BV(ADPS2) |
                               _BV(ADPS1) | _BV(ADPS0);
constexpr uint8_t adcPins = _BV(PF0) | _BV(PF1) | _BV(PF3);
constexpr uint8_t ledMask = _BV(PB2) | _BV(PB3) | _BV(PB4);
constexpr uint8_t channels[] = {0, 1, 3};
constexpr uint8_t ledBits[] = {_BV(PB2), _BV(PB3), _BV(PB4)};

uint8_t convert() {
    ADCSRA = adcControl | _BV(ADSC);
    while (!(ADCSRA & _BV(ADIF))) {}
    const uint8_t sample = ADCH;
    ADCSRA = adcControl | _BV(ADIF);
    return sample;
}

void setup() {
    DDRF &= ~adcPins;
    PORTF &= ~adcPins;
    DIDR0 |= _BV(ADC0D) | _BV(ADC1D) | _BV(ADC3D);
    PORTA = 0;
    DDRA = 0xFF;
    PORTB &= ~ledMask;
    DDRB |= ledMask;

    ADCSRB = 0;  // MUX5 = 0 for channels 0 to 7.
    ADMUX = _BV(REFS0) | _BV(ADLAR);
    ADCSRA = adcControl | _BV(ADIF);
}

void loop() {
    for (uint8_t i = 0; i < 3; ++i) {
        ADMUX = _BV(REFS0) | _BV(ADLAR) | channels[i];
        (void)convert();  // Extra settling sample after changing channel.
        PORTA = convert();
        PORTB = (PORTB & ~ledMask) | ledBits[i];
        delay(250);       // Keep this channel's LED visibly illuminated.
    }
}
```

The order is ADC0/PB2, ADC1/PB3, ADC3/PB4, then repeat. Shorten the display dwell if a higher update rate is required.
